    rows, cols = len(grid), len(grid[0])
    abstraction = [[0 for _ in range(cols)] for _ in range(rows)]

    for i in range(rows):
        for j in range(cols):
            if grid[i][j] == 'X':
                abstraction[i][j] = -1  # obstacle
            elif (i, j) == (rows - 1, cols - 1):  # goal state
                abstraction[i][j] = 2
            else:
