                            distance = abs(x - i) + abs(y - j)
                            if (x, y) == (rows - 1, cols - 1):  # goal state
                                min_distance = min(min_distance, distance)
                abstraction[i][j] = min_distance

    groups = []
    for i in range(rows):
        row = []
        for j in range(cols):
            if abstraction[i][j] != -1:
                row.append(abstraction[i][j])
            else:
                row.append(-1)
        groups.append(row)

    return groups


